            if sz == 8 {
                let fd = bsp::rf_filter(&buf);
                defmt::info!("{} => {:?}", sz, fd);
            } else {
                defmt::info!("partial data {} => {:?}", sz, buf);
            }
        } else {
            defmt::info!("serial data read error");
        }
    }
}

```

