```rust
struct ReadyService<F>(F);

impl<F, Req, Res, Err, Fut> Service for ReadyService<F>
where
    F: FnMut(Req) -> Fut,
    Fut: Future<Item=Res, Error=Err>,
{
    type Request = Req;
    type Response = Res;
    type Error = Err;
    type Future = Fut;

    fn poll_ready(&mut self) -> Poll<(), Self::Error> {
        // always ready
        Ok(Async::Ready(()))
    }

    fn call(&mut self, req: S::Request) -> S::Future {
        (self.0)(req)
    }
}
```

