raw_text:
The panic was triggered by callers issuing seek/seek_danger with a target lower than the scorer’s current doc()

PhraseScorer scorer had debug assertions [target >= self.doc(), so a backward seek violated the DocSet forward-only contract and crashed inside intersection.

Run this test


```rust
pub fn test_phrase_query_seek_backwards_safe() -> crate::Result<()> {
        let index = create_index(&["a b c", "a b c d"])?;
        let text_field = index.schema().get_field("text").unwrap();
        let searcher = index.reader()?.searcher();

        let terms: Vec<Term> = ["a", "b"]
            .iter()
            .map(|text| Term::from_field_text(text_field, text))
            .collect();
        let phrase_query = PhraseQuery::new(terms);
        let phrase_weight =
            phrase_query.phrase_weight(EnableScoring::disabled_from_schema(searcher.schema()))?;
        let mut scorer = phrase_weight.scorer(searcher.segment_reader(0), 1.0)?;

        // Initial doc is 0.
        assert_eq!(scorer.doc(), 0);

        // Seeking backwards (to the same or lower target) must not panic and should keep current.
        assert_eq!(scorer.seek(0), 0);
        assert_eq!(scorer.doc(), 0);

        // Move forward, then attempt to seek backwards again; scorer should remain at doc 1.
        assert_eq!(scorer.advance(), 1);
        assert_eq!(scorer.seek(0), 1);
        assert_eq!(scorer.doc(), 1);
        assert_eq!(scorer.advance(), TERMINATED);
        Ok(())
    }
```

