    fn test_async() {
        use leptos::reactive_graph::computed::*;
        use leptos::reactive_graph::prelude::*;
        use leptos::reactive_graph::signal::*;
        tokio_test::block_on(async move {
            leptos::spawn::Executor::init_tokio();
            let _guard = leptos::reactive_graph::diagnostics::SpecialNonReactiveZone::enter();

            let signal1 = RwSignal::new(0);
            let signal2 = RwSignal::new(0);

            let source1 = ArcMemo::new(move |_| signal1.get());
            let source2 = ArcMemo::new(move |_| signal2.get());
            let derived = ArcAsyncDerived::new_with_initial(Some(5), {
                let source1 = source1.clone();
                let source2 = source2.clone();
                move || {
                    println!("running");
                    let source1 = source1.clone();
                    let source2 = source2.clone();
                    async move {
                        let value1 = source1.get();
                        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
                        let value2 = source2.get();

                        value1 + value2
                    }
                }
            });

            // the value can be accessed synchronously as `Option<T>`
            assert_eq!(derived.get(), Some(5));
            // we can also .await the value, i.e., convert it into a Future
            assert_eq!(derived.clone().await, 5);
            assert_eq!(derived.get(), Some(5));

            signal1.set(1);
            derived.mark_dirty();
            // while the new value is still pending, the signal holds the old value
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            assert_eq!(derived.get(), Some(5));

            // setting multiple dependencies will hold until the latest change is ready
            signal2.set(1);
            assert_eq!(derived.await, 2);
        });
    }
}
