            cargoArtifacts = craneLib.buildDepsOnly args;
            buildArgs = args // {
              inherit cargoArtifacts;
              doCheck = false;
              cargoBuildCommand = "cargo build --profile release -v --features prod";
            };
            package = craneLib.buildPackage buildArgs;
          };
```

